ALTER TABLE ${ARENA_DB_SCHEMA}.academy_staff ADD COLUMN registration_request_id VARCHAR(36), ADD COLUMN registration_hash VARCHAR(64), ADD COLUMN login_email VARCHAR(255);
CREATE UNIQUE INDEX staff_registration_request_unique ON ${ARENA_DB_SCHEMA}.academy_staff(academy_id,registration_request_id) WHERE registration_request_id IS NOT NULL;
CREATE UNIQUE INDEX staff_login_email_unique ON ${ARENA_DB_SCHEMA}.academy_staff(login_email) WHERE login_email IS NOT NULL;
